const LESOTHO =
  "M 835.81 538.38 L 794.33 600.12 L 737.08 655.84 L 735.13 656.19 L 645.34 562.90 L 643.71 560.89 L 692.95 491.11 L 766.69 468.70 L 769.10 468.75 L 833.90 536.39 Z";

export function SAMap({ active, onSelect }: Props) {
  const byId = Object.fromEntries(LOCATIONS.map((l) => [l.id, l]));
  const routePoints = ROUTE_ORDER.map((id) => byId[id]);
  const linePath = routePoints
    .map((p, i) => `${i === 0 ? "M" : "L"} ${p.mapX} ${p.mapY}`)
    .join(" ");

  return (
    <div className="relative w-full max-w-[420px]">
      <svg viewBox="0 0 1058 946" className="w-full">
        <path
          d={`${MAINLAND} ${LESOTHO}`}
          fillRule="evenodd"
          fill="rgba(67,117,205,0.1)"
          stroke="rgba(253,255,248,0.55)"
          strokeWidth="4"
          strokeLinejoin="round"
        />

        <path
          d={linePath}
          fill="none"
          stroke="rgba(253,255,248,0.35)"
          strokeWidth="3"
          strokeDasharray="2 12"
          strokeLinecap="round"
        />

        {LOCATIONS.map((loc) => {
          const isActive = active === loc.id;
          return (
            <g
              key={loc.id}
              onClick={() => onSelect(loc.id)}
              className="cursor-pointer"
            >
              <circle cx={loc.mapX} cy={loc.mapY} r="32" fill="transparent" />
              <circle
                cx={loc.mapX}
                cy={loc.mapY}
                r={isActive ? 16 : 11}
                fill={isActive ? "#4375cd" : "transparent"}
                stroke={isActive ? "#fdfff8" : "rgba(253,255,248,0.6)"}
                strokeWidth={isActive ? 4 : 3}
                className="transition-all duration-200"
              />
              <text
                x={loc.mapX}
                y={loc.mapY - 24}
                textAnchor="middle"
                className="pointer-events-none select-none"
                style={{
                  fontFamily: "var(--font-mono)",
                  fontSize: 20,
                  fill: isActive ? "#fdfff8" : "rgba(253,255,248,0.65)",
                  fontWeight: isActive ? 600 : 500,
                }}
              >
                {loc.shortName}
              </text>
            </g>
          );
        })}
      </svg>
    </div>
  );
}
